import { isArray } from 'lodash-es';
import React, {
  forwardRef,
  ReactElement,
  useEffect,
  useRef,
  useState,
} from 'react';
import { isElement } from 'react-is';

import {
  BasicChartTooltip,
  BasicChartTooltipProps,
} from './BasicChartTooltip/BasicChartTooltip.js';
import { InteractiveChartTooltipSeries } from './InteractiveChartTooltipSeries.js';
import { InteractiveChartTooltipVirtualizedSeries } from './InteractiveChartTooltipVirtualizedSeries.js';
import { useMergeRefs } from '../../../../../../core/hooks/useMergeRefs.js';
import { MouseCoordinate } from '../../../../types/overlays.js';
import { TooltipItem } from '../../../../types/tooltip.js';
import { useChartTooltip } from '../../shared/hooks/useChartTooltip.js';
import { InteractiveTooltipContext } from '../context/InteractiveTooltipContext.js';
import { Actions } from '../slots/Actions.js';
import { Body } from '../slots/Body.js';
import { Header } from '../slots/Header.js';
import { VirtualEstimatedSize } from '../types/virtual-estimated-size.js';

const VIRTUALIZED_THRESHOLD = 100;

export interface InteractiveChartTooltipProps {
  pinned?: boolean;
  itemSize?: VirtualEstimatedSize;
  position: MouseCoordinate;
  onMouseLeave?: (event?: React.MouseEvent) => void;
  onScrollContent?: (event: Event) => void;
}

/**
 * Iterate the children to load the slots
 * @param children -
 */
function iterateSlots(children?: React.ReactNode): {
  Header?: ReactElement;
  Body?: ReactElement[];
  Actions?: ReactElement[];
} {
  const slots = { Header: undefined, Body: undefined, Actions: undefined };

  React.Children.forEach(children, (child) => {
    if (isElement(child)) {
      if (child.type === Header) {
        slots['Header'] = isElement(child.props.children)
          ? child.props.children
          : undefined;
      }
      if (child.type === Body) {
        if (isElement(child.props.children)) {
          slots['Body'] = child.props.children;
        } else {
          if (isArray(child.props.children)) {
            slots['Body'] = React.Children.map(
              child.props.children,
              (childElement) =>
                isElement(childElement) ? childElement : undefined,
            ).filter((v: ReactElement) => v !== undefined);
          }
        }
      }
      if (child.type === Actions) {
        slots['Actions'] = isElement(child.props.children)
          ? child.props.children
          : undefined;
      }
    }
  });

  return slots;
}

/**
 * Tooltip specific to the TimeseriesChart and Categorical bar chart.
 */
const _InteractiveChartTooltip = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  BasicChartTooltipProps & InteractiveChartTooltipProps
>((props, forwardedRef) => {
  const {
    pinned = false,
    chartRef,
    position,
    itemSize,
    children,
    onMouseLeave,
    onScrollContent,
  } = props;
  const chartTooltipRef = useRef<HTMLDivElement>(null);
  const mergedRefs = useMergeRefs([forwardedRef, chartTooltipRef]);

  const [selectedItem, selectItem] = useState<TooltipItem | undefined>(
    undefined,
  );
  const [hasScrollbar, setHasScrollbar] = useState<boolean>(false);
  const onItemSelected = (e: React.MouseEvent, item?: TooltipItem) => {
    e.stopPropagation(); // prevent unpinning
    selectItem(item);
  };

  const { placement, updateTooltipPosition } = useChartTooltip(
    chartTooltipRef.current,
  );

  useEffect(() => {
    if (!pinned) {
      updateTooltipPosition(position);
    }
  }, [position]);

  useEffect(() => {
    return () => {
      onMouseLeave && onMouseLeave();
    };
  }, []);

  const { Header, Body } = iterateSlots(children);

  return (
    <InteractiveTooltipContext.Provider
      value={{
        selectedItem,
        selectItem: onItemSelected,
        hasScrollbar,
        setHasScrollbar,
      }}
    >
      <BasicChartTooltip
        ref={mergedRefs}
        placement={placement}
        chartRef={chartRef}
        onMouseLeave={onMouseLeave}
        pinned={pinned}
      >
        {Body && Body.length > VIRTUALIZED_THRESHOLD ? (
          <InteractiveChartTooltipVirtualizedSeries
            pinned={pinned}
            itemSize={itemSize}
            header={Header}
            body={Body}
            pointerEvents={pinned}
            onScrollContent={onScrollContent}
          />
        ) : (
          <InteractiveChartTooltipSeries
            pinned={pinned}
            header={Header}
            body={Body}
            pointerEvents={pinned}
            onScrollContent={onScrollContent}
          />
        )}
      </BasicChartTooltip>
    </InteractiveTooltipContext.Provider>
  );
});

_InteractiveChartTooltip['displayName'] = 'InteractiveChartTooltip';

/** Slot component for interactive chart tooltip */
export const InteractiveChartTooltip = Object.assign(_InteractiveChartTooltip, {
  Header,
  Body,
  Actions,
});
